// Normalizes input and validates crop / disease / pest for IPDM
const body = $json.body || $json;
return [{
  crop: (body.crop || 'Crop').trim(),
  condition: (body.disease || body.pest || 'Condition').trim(),
  language: body.language || 'en'
}];

// PostGIS proximity dispatcher: calculates 10 km radius recipients
const b = $json.body || $json;
return [{
  farmerId: b.farmerId,
  crop: b.crop,
  pest: b.pest,
  severity: b.severity,
  latitude: b.latitude,
  longitude: b.longitude,
  message: `Warning: High ${b.pest} activity reported in ${b.crop} fields within 10 km.`
}];

